mapper.select:
SELECT 
FROM author_book_collaborator c
JOIN author a ON a.id = c.collaborator_author_id
JOIN user u ON u.id = a.user_id
WHERE c.id = #{collaboratorId}
  AND c.book_id = #{bookId}
  AND c.owner_author_id = #{ownerAuthorId}
LIMIT 1

mapper.delete:
DELETE FROM author_book_collaborator
WHERE id = #{collaboratorId}
  AND book_id = #{bookId}
  AND owner_author_id = #{ownerAuthorId}
  AND version = #{expectedVersion}
